import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            M = int(next(iterator))
            K = int(next(iterator))
        except StopIteration:
            break

        if N == 1 or M == 1:
            stones_per_cell = K
            results.append(str(stones_per_cell))
            continue

        dist = {}
        queue = deque()
        queue.append((1, 1))
        dist[(1, 1)] = 0

        while queue:
            r, c = queue.popleft()
            d = dist[(r, c)]

            if r < N:
                nr, nc = r + 1, c
                if (nr, nc) not in dist:
                    dist[(nr, nc)] = d + 1
                    queue.append((nr, nc))
            if c < M:
                nr, nc = r, c + 1
                if (nr, nc) not in dist:
                    dist[nr, nc] = d + 1
                    queue.append((nr, nc))

        max_dist = dist.get((N, M), 0)

        total_paths = 0
        path_counts = [0] * (max_dist + 1)

        for d in range(max_dist + 1):
            count = 0
            for (r, c) in dist:
                if dist[(r, c)] == d:
                    count += 1
            path_counts[d] = count

        used_cells = set()
        remaining_K = K
        max_stones = 0

        for d in range(max_dist + 1):
            available = path_counts[d]
            if available == 0:
                continue

            if remaining_K == 0:
                break

            num_paths_from_layer = min(available, remaining_K)
            if num_paths_from_layer > 0:
                current_layer_stones = (num_paths_from_layer + available - 1) // available
                max_stones = max(max_stones, current_layer_stones)
                remaining_K -= num_paths_from_layer

        results.append(str(max_stones))

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
